// Run from apps/server: node --input-type=module -e "$(cat grok-status-driver.mjs)"
import * as NodeServices from "@effect/platform-node/NodeServices";
import * as Effect from "effect/Effect";
import * as Schema from "effect/Schema";
import * as ChildProcessSpawner from "effect/process/ChildProcessSpawner";
import { GrokSettings } from "@t3tools/provider-grok/settings";
import { checkGrokProviderStatus } from "@t3tools/provider-grok/testing";

const program = Effect.gen(function* () {
  const spawner = yield* ChildProcessSpawner.ChildProcessSpawner;
  const spawns = [];
  const recording = ChildProcessSpawner.make((command) => {
    if (command._tag === "StandardCommand")
      spawns.push({ command: command.command, args: command.args.join(" "), detached: command.options.detached, shell: command.options.shell });
    return spawner.spawn(command);
  });
  const t0 = Date.now();
  const status = yield* checkGrokProviderStatus(Schema.decodeSync(GrokSettings)({ enabled: true }), process.env).pipe(
    Effect.provideService(ChildProcessSpawner.ChildProcessSpawner, recording),
  );
  console.log(JSON.stringify({ platform: process.platform, elapsedMs: Date.now() - t0, spawns, status: status.status, installed: status.installed, version: status.version, message: status.message ?? null, models: (status.models ?? []).length }, null, 2));
});
await Effect.runPromise(program.pipe(Effect.provide(NodeServices.layer)));
  ```
